CREATE TABLE IF NOT EXISTS gis_state_constrained_resolution_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), country_code text NOT NULL, source_provider text NOT NULL, target_provider text NOT NULL, source_count integer NOT NULL DEFAULT 0, candidate_count integer NOT NULL DEFAULT 0, high_confidence integer NOT NULL DEFAULT 0, ambiguous integer NOT NULL DEFAULT 0, unresolved integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'Running', created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE IF NOT EXISTS gis_state_constrained_matches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES gis_state_constrained_resolution_runs(id) ON DELETE CASCADE, source_feature_id uuid NOT NULL REFERENCES gis_spatial_features(id) ON DELETE CASCADE, target_feature_id uuid REFERENCES gis_spatial_features(id) ON DELETE CASCADE, canonical_state_code text, source_lga_code text, target_lga_code text, score numeric(6,5) NOT NULL DEFAULT 0, confidence text NOT NULL DEFAULT 'Unresolved', review_required boolean NOT NULL DEFAULT true, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_gis_state_constrained_run ON gis_state_constrained_matches(run_id,confidence,review_required);